class Solution:
    def threeSumMulti(self, arr: list[int], target: int) -> int:
        MOD = 10**9 + 7
        cnt = Counter(arr)                 # at most 101 distinct values since 0 <= arr[i] <= 100
        vals = sorted(cnt)
        total = 0
        for i, a in enumerate(vals):       # O(U^2) pairs of distinct values, U <= 101
            for b in vals[i:]:             # b >= a
                c = target - a - b
                if c < b or c not in cnt:  # enforce a <= b <= c so each value triple is counted once
                    continue
                if a == b == c:
                    total += cnt[a] * (cnt[a] - 1) * (cnt[a] - 2) // 6
                elif a == b:
                    total += cnt[a] * (cnt[a] - 1) // 2 * cnt[c]
                elif b == c:
                    total += cnt[a] * cnt[b] * (cnt[b] - 1) // 2
                else:
                    total += cnt[a] * cnt[b] * cnt[c]
        return total % MOD

